+import Yoga from 'yoga-layout';
+import {type DOMElement, type DOMNode} from './dom.js';
+
+type Track =
+	| {type: 'fixed'; value: number}
+	| {type: 'fr'; value: number}
+	| {type: 'auto'}
+	| {type: 'minmax'; min: number; max: number | undefined};
+
+type Placement = {start: number; end: number};
+type GridItem = {node: DOMElement; column: Placement; row: Placement};
+
+const parseTracks = (template: string | undefined): Track[] => {
+	if (!template?.trim()) return [{type: 'auto'}];
+	const tokens = template.match(/minmax\\([^)]*\\)|\\S+/g) ?? [];
+	return tokens.map(token => {
+		const minmax = /^minmax\\(\\s*(\\d+)\\s*,\\s*(\\d+(?:\\.\\d+)?fr|\\d+)\\s*\\)$/.exec(token);
+		if (minmax) {
+			return {type: 'minmax', min: Number(minmax[1]), max: minmax[2].endsWith('fr') ? Number.parseFloat(minmax[2]) : undefined};
+		}
+		if (token === 'auto') return {type: 'auto'};
+		if (/^\\d+(?:\\.\\d+)?fr$/.test(token)) return {type: 'fr', value: Number.parseFloat(token)};
+		if (/^\\d+(?:\\.\\d+)?$/.test(token)) return {type: 'fixed', value: Number(token)};
+		throw new Error(`Invalid grid track size: ${token}`);
+	});
+};
+
+const parsePlacement = (value: number | string | undefined): Placement | undefined => {
+	if (typeof value === 'number') return {start: value - 1, end: value};
+	if (!value) return;
+	const match = /^(\\d+)\\s*\\/\\s*(\\d+)$/.exec(value.trim());
+	if (!match) throw new Error(`Invalid grid placement: ${value}`);
+	return {start: Number(match[1]) - 1, end: Number(match[2]) - 1};
+};
+
+const gap = (node: DOMElement, name: 'columnGap' | 'rowGap') => node.style[name] ?? node.style.gap ?? 0;
+
+const resetDimension = (node: DOMElement, name: 'width' | 'height') => {
+	const value = node.style[name];
+	if (typeof value === 'number') node.yogaNode?.[name === 'width' ? 'setWidth' : 'setHeight'](value);
+	else if (typeof value === 'string') node.yogaNode?.[name === 'width' ? 'setWidthPercent' : 'setHeightPercent'](Number.parseInt(value, 10));
+	else node.yogaNode?.[name === 'width' ? 'setWidthAuto' : 'setHeightAuto']();
+};
+
+const resetManagedGridItems = (node: DOMElement): void => {
+	if (node.internal_gridManaged) {
+		resetDimension(node, 'width');
+		resetDimension(node, 'height');
+		node.yogaNode?.setPositionType(node.style.position === 'absolute' ? Yoga.POSITION_TYPE_ABSOLUTE : Yoga.POSITION_TYPE_RELATIVE);
+		node.internal_gridManaged = false;
+	}
+	for (const child of node.childNodes) if (child.nodeName !== '#text') resetManagedGridItems(child);
+};
+
+const trackSizes = (tracks: Track[], available: number, itemSizes: number[], trackGap: number): number[] => {
+	const sizes = tracks.map((track, index) => track.type === 'fixed' ? track.value : track.type === 'minmax' ? track.min : track.type === 'auto' ? itemSizes[index] ?? 0 : 0);
+	const frTotal = tracks.reduce((total, track) => total + (track.type === 'fr' ? track.value : track.type === 'minmax' ? (track.max ?? 0) : 0), 0);
+	if (frTotal > 0) {
+		const remaining = Math.max(0, available - sizes.reduce((total, size) => total + size, 0) - trackGap * Math.max(0, tracks.length - 1));
+		tracks.forEach((track, index) => {
+			const factor = track.type === 'fr' ? track.value : track.type === 'minmax' ? (track.max ?? 0) : 0;
+			sizes[index] += remaining * factor / frTotal;
+		});
+	}
+	return sizes;
+};
+
+const placeItems = (container: DOMElement, columns: number): GridItem[] => {
+	const occupied = new Set<string>();
+	const items: GridItem[] = [];
+	let cursor = 0;
+	const available = (column: Placement, row: Placement) => {
+		for (let y = row.start; y < row.end; y++) for (let x = column.start; x < column.end; x++) if (occupied.has(`${x}:${y}`)) return false;
+		return true;
+	};
+	const reserve = (column: Placement, row: Placement) => {
+		for (let y = row.start; y < row.end; y++) for (let x = column.start; x < column.end; x++) occupied.add(`${x}:${y}`);
+	};
+	for (const node of container.childNodes) {
+		if (node.nodeName === '#text' || !node.yogaNode || node.yogaNode.getDisplay() === Yoga.DISPLAY_NONE) continue;
+		let column = parsePlacement(node.style.gridColumn);
+		let row = parsePlacement(node.style.gridRow);
+		if (column && column.end > columns) throw new Error('Grid item exceeds the number of grid columns');
+		if (!column || !row) {
+			for (let index = cursor; ; index++) {
+				const candidateColumn = column ?? {start: index % columns, end: index % columns + 1};
+				const candidateRow = row ?? {start: Math.floor(index / columns), end: Math.floor(index / columns) + 1};
+				if (available(candidateColumn, candidateRow)) { column = candidateColumn; row = candidateRow; cursor = index + 1; break; }
+			}
+		}
+		reserve(column!, row!);
+		items.push({node, column: column!, row: row!});
+	}
+	return items;
+};
+
+const layoutGrid = (container: DOMElement): void => {
+	const columns = parseTracks(container.style.gridTemplateColumns);
+	const rows = parseTracks(container.style.gridTemplateRows);
+	const columnGap = gap(container, 'columnGap');
+	const rowGap = gap(container, 'rowGap');
+	const items = placeItems(container, columns.length);
+	const contentWidth = container.yogaNode!.getComputedWidth() - container.yogaNode!.getComputedPadding(Yoga.EDGE_LEFT) - container.yogaNode!.getComputedPadding(Yoga.EDGE_RIGHT) - container.yogaNode!.getComputedBorder(Yoga.EDGE_LEFT) - container.yogaNode!.getComputedBorder(Yoga.EDGE_RIGHT);
+	const columnAutoSizes = columns.map((_, index) => Math.max(0, ...items.filter(item => item.column.start === index && item.column.end === index + 1).map(item => item.node.yogaNode!.getComputedWidth())));
+	const columnSizes = trackSizes(columns, contentWidth, columnAutoSizes, columnGap);
+	const rowCount = Math.max(rows.length, ...items.map(item => item.row.end), 1);
+	while (rows.length < rowCount) rows.push({type: 'auto'});
+	const x = (index: number) => columnSizes.slice(0, index).reduce((total, size) => total + size, 0) + columnGap * index;
+	for (const item of items) {
+		const width = x(item.column.end) - x(item.column.start) - columnGap;
+		item.node.yogaNode!.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		item.node.yogaNode!.setPosition(Yoga.EDGE_LEFT, x(item.column.start));
+		item.node.yogaNode!.setWidth(width);
+		item.node.yogaNode!.setHeightAuto();
+		item.node.internal_gridManaged = true;
+	}
+	const rowAutoSizes = rows.map((_, index) => Math.max(0, ...items.filter(item => item.row.start === index && item.row.end === index + 1).map(item => item.node.yogaNode!.getComputedHeight())));
+	const specifiedHeight = container.style.height;
+	const contentHeight = typeof specifiedHeight === 'number' ? specifiedHeight : rowAutoSizes.reduce((total, size) => total + size, 0) + rowGap * Math.max(0, rows.length - 1);
+	const rowSizes = trackSizes(rows, contentHeight, rowAutoSizes, rowGap);
+	const y = (index: number) => rowSizes.slice(0, index).reduce((total, size) => total + size, 0) + rowGap * index;
+	for (const item of items) {
+		item.node.yogaNode!.setPosition(Yoga.EDGE_TOP, y(item.row.start));
+		item.node.yogaNode!.setHeight(y(item.row.end) - y(item.row.start) - rowGap);
+	}
+	if (typeof specifiedHeight !== 'number') container.yogaNode!.setHeight(y(rows.length) - rowGap);
+};
+
+const visitGrids = (node: DOMElement): void => {
+	if (node.style.display === 'grid') layoutGrid(node);
+	for (const child of node.childNodes) if (child.nodeName !== '#text') visitGrids(child);
+};
+
+export const calculateLayout = (root: DOMElement, width: number): void => {
+	resetManagedGridItems(root);
+	root.yogaNode!.setWidth(width);
+	root.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+	visitGrids(root);
+	root.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+	visitGrids(root);
+	root.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+};
